class SagaCoordinator:
    def execute_saga(self, steps):
        executed = []
        try:
            for forward_fn, compensate_fn in steps:
                forward_fn()
                executed.append(compensate_fn)
        except Exception:
            for comp_fn in reversed(executed):
                try:
                    comp_fn()
                except Exception:
                    pass
            raise

