import React, { useState, useEffect } from 'react';

export default function LiveSearch({ fetchResults }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  useEffect(() => {
    let active = true;
    if (!query) {
      setResults([]);
      return;
    }

    fetchResults(query).then(data => {
      if (active) {
        setResults(data);
      }
    });

    return () => {
      active = false;
    };
  }, [query, fetchResults]);

  return (
